package com.procurement.approvalhistory.service;import com.procurement.approvalhistory.dto.response.*;import com.procurement.approvalhistory.entity.ApprovalHistory;import com.procurement.approvalhistory.mapper.*;import com.procurement.approvalhistory.repository.*;import com.procurement.common.exception.*;import com.procurement.common.response.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class ApprovalHistoryServiceImpl implements ApprovalHistoryService{private final ApprovalHistoryRepository repo;private final ApprovalHistoryMapper mapper;public ApprovalHistoryServiceImpl(ApprovalHistoryRepository r,ApprovalHistoryMapper m){repo=r;mapper=m;}@Transactional(readOnly=true)public PageResponse<ApprovalHistoryResponse>search(Long requestId,Pageable p){Specification<ApprovalHistory>s=requestId==null?null:(r,q,b)->b.equal(r.get("purchaseRequest").get("id"),requestId);Page<ApprovalHistoryResponse>x=repo.findAll(s,p).map(mapper::toResponse);return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public ApprovalHistoryResponse getById(Long id){return repo.findById(id).map(mapper::toResponse).orElseThrow(()->new ResourceNotFoundException("Approval history not found: "+id));}}
